<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { store as storeChecklist, update as updateChecklist } from '@/actions/App/Http/Controllers/ChecklistTarefaController';
import { store as storeComentario } from '@/actions/App/Http/Controllers/ComentarioTarefaController';
import updateStatus from '@/actions/App/Http/Controllers/StatusTarefaController';
import { index as tarefasIndex } from '@/routes/tarefas';

defineOptions({
    layout: {
        breadcrumbs: [{ title: 'Tarefas', href: tarefasIndex() }],
    },
});

type Tarefa = { id: number; titulo: string; descricao: string | null; status: string; prioridade: string; prazo: string | null; data_inicio: string | null; estimativa_minutos: number | null; responsavel: { name: string; email: string } | null; criador: { name: string }; lista: { nome: string; equipe: { nome: string } }; itens_checklist: { id: number; titulo: string; concluido: boolean }[]; comentarios: { id: number; comentario: string; created_at: string; autor: { name: string } }[]; historicos: { id: number; evento: string; campo: string | null; created_at: string; usuario: { name: string } | null }[] };
const props = defineProps<{ tarefa: Tarefa }>();
const statusForm = useForm({ status: props.tarefa.status });
const checklistForm = useForm({ titulo: '' });
const commentForm = useForm({ comentario: '' });
const changeStatus = () => statusForm.patch(updateStatus(props.tarefa).url);
const addChecklist = () => checklistForm.post(storeChecklist(props.tarefa).url, { preserveScroll: true, onSuccess: () => checklistForm.reset() });
const toggleChecklist = (item: Tarefa['itens_checklist'][number]) => useForm({ concluido: !item.concluido }).patch(updateChecklist([props.tarefa, item]).url, { preserveScroll: true });
const addComment = () => commentForm.post(storeComentario(props.tarefa).url, { preserveScroll: true, onSuccess: () => commentForm.reset() });
const label = (value: string) => value.replaceAll('_', ' ');
</script>

<template>
    <Head :title="tarefa.titulo" />
    <main class="w-full space-y-6 p-4 lg:p-6"><Link :href="tarefasIndex()" class="text-sm text-muted-foreground hover:text-foreground">← Voltar para tarefas</Link><div class="grid gap-6 lg:grid-cols-[minmax(0,1fr)_18rem]"><section class="space-y-6"><article class="rounded-xl border bg-card p-5 shadow-sm"><div class="flex flex-wrap justify-between gap-4"><div><p class="text-sm text-muted-foreground">{{ tarefa.lista.equipe.nome }} · {{ tarefa.lista.nome }}</p><h1 class="mt-1 text-2xl font-semibold">{{ tarefa.titulo }}</h1></div><span class="h-fit rounded-full bg-muted px-3 py-1 text-sm capitalize">{{ tarefa.prioridade }}</span></div><p class="mt-5 whitespace-pre-line text-sm leading-6 text-muted-foreground">{{ tarefa.descricao || 'Sem descrição.' }}</p></article><section class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Checklist</h2><div class="mt-4 space-y-2"><label v-for="item in tarefa.itens_checklist" :key="item.id" class="flex cursor-pointer items-center gap-3 rounded-md p-2 hover:bg-muted/50"><input :checked="item.concluido" type="checkbox" @change="toggleChecklist(item)" /><span :class="item.concluido ? 'text-muted-foreground line-through' : ''">{{ item.titulo }}</span></label><p v-if="!tarefa.itens_checklist.length" class="text-sm text-muted-foreground">Nenhum item adicionado.</p></div><form class="mt-4 flex gap-2" @submit.prevent="addChecklist"><input v-model="checklistForm.titulo" class="h-9 min-w-0 flex-1 rounded-md border bg-background px-3 text-sm" placeholder="Adicionar item" /><button class="rounded-md border px-3 text-sm font-medium">Adicionar</button></form></section><section class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Comentários</h2><div class="mt-4 space-y-4"><div v-for="comentario in tarefa.comentarios" :key="comentario.id"><div class="flex gap-2 text-sm"><span class="font-medium">{{ comentario.autor.name }}</span><span class="text-muted-foreground">{{ new Date(comentario.created_at).toLocaleString('pt-BR') }}</span></div><p class="mt-1 whitespace-pre-line text-sm">{{ comentario.comentario }}</p></div><p v-if="!tarefa.comentarios.length" class="text-sm text-muted-foreground">Nenhum comentário ainda.</p></div><form class="mt-5 space-y-2" @submit.prevent="addComment"><textarea v-model="commentForm.comentario" rows="3" class="w-full rounded-md border bg-background px-3 py-2 text-sm" placeholder="Escreva um comentário" /><button :disabled="commentForm.processing" class="rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Comentar</button></form></section></section><aside class="space-y-4"><section class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Status</h2><form class="mt-3 flex gap-2" @submit.prevent="changeStatus"><select v-model="statusForm.status" class="h-9 min-w-0 flex-1 rounded-md border bg-background px-3 text-sm"><option value="pendente">Pendente</option><option value="em_andamento">Em andamento</option><option value="bloqueada">Bloqueada</option><option value="concluida">Concluída</option><option value="cancelada">Cancelada</option></select><button :disabled="statusForm.processing" class="rounded-md border px-3 text-sm">Salvar</button></form><p v-if="statusForm.errors.status" class="mt-2 text-xs text-destructive">{{ statusForm.errors.status }}</p></section><section class="rounded-xl border bg-card p-5 text-sm shadow-sm"><h2 class="font-semibold">Detalhes</h2><dl class="mt-4 space-y-3"><div><dt class="text-muted-foreground">Responsável</dt><dd>{{ tarefa.responsavel?.name ?? 'Não atribuído' }}</dd></div><div><dt class="text-muted-foreground">Prazo</dt><dd>{{ tarefa.prazo ? new Date(tarefa.prazo).toLocaleString('pt-BR') : 'Não definido' }}</dd></div><div><dt class="text-muted-foreground">Criada por</dt><dd>{{ tarefa.criador.name }}</dd></div></dl></section><section class="rounded-xl border bg-card p-5 text-sm shadow-sm"><h2 class="font-semibold">Histórico</h2><ol class="mt-4 space-y-3"><li v-for="evento in tarefa.historicos" :key="evento.id"><p class="capitalize">{{ label(evento.evento) }}</p><p class="text-xs text-muted-foreground">{{ evento.usuario?.name ?? 'Sistema' }} · {{ new Date(evento.created_at).toLocaleString('pt-BR') }}</p></li></ol></section></aside></div></main>
</template>
